  uint64_t schway_entry_output = SCHWAY_MAIN(schway_entry_input, 0u);
  if (!schway_write_u64_plain(schway_entry_output) || !schway_write_literal("\n")) schway_application_output_failure();
  const char *schway_evidence_path = getenv("SCHWAY_APP_EVIDENCE_PATH");
  if (schway_evidence_path != NULL && schway_evidence_path[0] != '\0') {
    FILE *schway_evidence_file = fopen(schway_evidence_path, "wb");
    if (schway_evidence_file != NULL) {
      schway_output_stream = schway_evidence_file;
      schway_output_limit = SCHWAY_EVIDENCE_OUTPUT_LIMIT;
      schway_output_count = 0u;
      if (schway_event_overflow) {
        (void)schway_write_literal("{\"schema\":\"lang.app-capture/1\",\"status\":\"capacity_exhausted\"}\n");
      } else {
        (void)schway_write_literal("{\"schema\":\"lang.app-capture/1\",\"status\":\"complete\",\"execution\":{\"schema\":\"lang.execution/2\",\"outcome\":{\"kind\":\"returned\",\"value\":");
        (void)schway_write_u64(schway_entry_output);
        (void)schway_write_literal("},\"events\":[");
        (void)schway_write_events();
        (void)schway_write_literal("],\"live_resources\":");
        (void)schway_write_live_resources();
        (void)schway_write_literal("}}\n");
      }
      (void)fclose(schway_evidence_file);
      if (schway_evidence_output_overflow) {
        FILE *schway_overflow_file = fopen(schway_evidence_path, "wb");
        if (schway_overflow_file != NULL) {
          static const char schway_capacity_capture[] = "{\"schema\":\"lang.app-capture/1\",\"status\":\"capacity_exhausted\"}\n";
          (void)fwrite(schway_capacity_capture, 1u, sizeof schway_capacity_capture - 1u, schway_overflow_file);
          (void)fclose(schway_overflow_file);
        }
      }
    }
  }
  return schway_application_output_failed ? 65 : 0;
}
